import functools, time
def timed(fn):
    @functools.wraps(fn)
    def w(*a, **k):
        t0 = time.perf_counter()
        r = fn(*a, **k)
        print(f'{fn.__name__}: {time.perf_counter()-t0:.3f}s')
        return r
    return w
functools.wraps 不能省，否则函数名和文档全丢，调试和栈信息都没法看。

